import{_ as l,o as e,c as t,a6 as i}from"./chunks/framework.BBIckNDn.js";const u=JSON.parse('{"title":"第3章 メモリとキャッシュ ── 現代ゲーム最適化の主戦場","description":"","frontmatter":{"title":"第3章 メモリとキャッシュ ── 現代ゲーム最適化の主戦場","study":{"source":"IT教本","kind":"学習ガイド","status":"学習計画・概要","summary":"現代のゲームの速度はCPUの計算速度ではなく、メモリアクセスで決まる。 メインメモリへのアクセス待ちは、レジスタを使う演算より長くなりやすい。ECS(第15章)も UnityのDOTS(第16章)も、データ指向設計(DOD)も、すべて"}},"headers":[],"relativePath":"guide/low-level/memory-and-cache.md","filePath":"guide/low-level/memory-and-cache.md"}'),n={name:"guide/low-level/memory-and-cache.md"};function s(r,a,o,d,c,h){return e(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="第3章-メモリとキャッシュ-──-現代ゲーム最適化の主戦場" tabindex="-1">第3章 メモリとキャッシュ ── 現代ゲーム最適化の主戦場 <a class="header-anchor" href="#第3章-メモリとキャッシュ-──-現代ゲーム最適化の主戦場" aria-label="Permalink to &quot;第3章 メモリとキャッシュ ── 現代ゲーム最適化の主戦場&quot;">​</a></h1><h2 id="学ぶ理由" tabindex="-1">学ぶ理由 <a class="header-anchor" href="#学ぶ理由" aria-label="Permalink to &quot;学ぶ理由&quot;">​</a></h2><p><strong>現代のゲームの速度はCPUの計算速度ではなく、メモリアクセスで決まる。</strong> メインメモリへのアクセス待ちは、レジスタを使う演算より長くなりやすい。ECS(第15章)も UnityのDOTS(第16章)も、データ指向設計(DOD)も、すべて 「キャッシュに優しいメモリレイアウト」を実現するための技術である。 この章を理解すると、それらの流行が全部「当然の帰結」に見えるようになる。</p><h2 id="到達目標" tabindex="-1">到達目標 <a class="header-anchor" href="#到達目標" aria-label="Permalink to &quot;到達目標&quot;">​</a></h2><ul><li>メモリ階層(レジスタ→L1→L2→L3→DRAM)と各レイテンシの桁を言える</li><li>キャッシュライン(64バイト)・空間局所性・時間局所性を説明できる</li><li>AoSとSoAの違いと、どちらがいつ速いかを説明できる</li><li>構造体のアラインメントとパディングを図示できる</li><li>false sharing、プリフェッチの概念を説明できる</li></ul><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to &quot;前提知識&quot;">​</a></h2><p>第1章(バイト・ビット)、第2章(CPUサイクルの感覚)。</p><h2 id="学ぶ内容" tabindex="-1">学ぶ内容 <a class="header-anchor" href="#学ぶ内容" aria-label="Permalink to &quot;学ぶ内容&quot;">​</a></h2><ol><li><strong>メモリ階層とレイテンシの桁感覚(数値は説明用の目安)</strong><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>レジスタ:      命令のオペランド。演算の遅延は命令・CPUに依存</span></span>
<span class="line"><span>L1キャッシュ: 約 4 サイクル  (32〜48KB/コア)</span></span>
<span class="line"><span>L2キャッシュ: 約 12 サイクル (512KB〜1MB/コア)</span></span>
<span class="line"><span>L3キャッシュ: 約 40 サイクル (数十MB共有)</span></span>
<span class="line"><span>DRAM:        約 200+ サイクル (数十GB)</span></span>
<span class="line"><span>SSD:         数万〜サイクル換算で数百万</span></span></code></pre></div>容量・遅延はCPU/アクセス条件で異なる。DRAM待ちと独立な演算は重ねられるが、 依存関係や帯域の制約があり、この表から実行時間がそのまま決まるわけではない。</li><li><strong>キャッシュの仕組み</strong><ul><li>キャッシュラインはデータを管理・転送する単位。64バイトは多くのCPUの例で、 対象CPUの仕様を確認する。同じラインの近隣データを使うと追加の転送を減らしやすい</li><li>空間局所性(隣を使え)・時間局所性(すぐまた使え)</li><li>セットアソシアティブ、エビクション(LRU近似)は概念だけ</li><li>書き込み: ライトバック、ダーティライン</li></ul></li><li><strong>データレイアウト設計</strong><ul><li><strong>AoS (Array of Structures)</strong>: <code>struct Enemy{pos, hp, name...}</code> の配列 → 1体全体を触るゲームロジック向き</li><li><strong>SoA (Structure of Arrays)</strong>: pos[], hp[] を別配列 → 全体のposだけを走査する物理・カリングで有利になりやすい。実際のアクセスで比較する</li><li>ホット/コールド分離: 毎フレーム触るデータと稀にしか触らないデータを 別の構造体に分ける</li></ul></li><li><strong>アラインメントとパディング</strong><ul><li>型には整列要件があり、構造体にはパディングが入ることがある。 <code>struct{char a; int b;}</code> が8バイトなのは、intのサイズ/整列が4バイト等の場合の例</li><li>メンバ並び替えでサイズが縮む実例</li><li>SIMD型・命令には整列条件がある場合がある。16バイト整列の例は <code>alignas(16)</code>。 floatを4つ並べただけで常に16バイト整列が必須になるわけではない</li></ul></li><li><strong>ポインタ追跡の代償</strong><ul><li>連結リスト・<code>new</code>で散らばったオブジェクト・仮想関数テーブル参照は すべて「ポインタの先へジャンプ」=キャッシュミスの温床</li><li>「配列は正義」の定量的根拠</li></ul></li><li><strong>マルチコアとキャッシュ(さわりだけ、詳細は第8章)</strong><ul><li>コヒーレンシ(MESI)の存在</li><li><strong>false sharing</strong>: 別スレッドが同じキャッシュライン上の別変数を 書くとキャッシュの無効化が増えて遅くなる場合がある。対象のラインサイズを考え、 共有する必要のないデータを分離して計測する</li></ul></li><li><strong>計測して確かめる</strong><ul><li>VSの診断ツール、または簡易ベンチマークで「理論を数字で確認」する習慣</li></ul></li></ol><h2 id="重要概念" tabindex="-1">重要概念 <a class="header-anchor" href="#重要概念" aria-label="Permalink to &quot;重要概念&quot;">​</a></h2><ul><li><strong>「計算は無料、メモリは高い」</strong> ── 現代最適化の第一原理</li><li><strong>キャッシュライン64バイト</strong> ── データ設計の基本単位</li><li><strong>局所性</strong> ── 速いプログラムとは局所性の高いプログラム</li><li><strong>レイアウトはアルゴリズムと同じくらい性能を決める</strong></li></ul><h2 id="ゲーム開発との関係" tabindex="-1">ゲーム開発との関係 <a class="header-anchor" href="#ゲーム開発との関係" aria-label="Permalink to &quot;ゲーム開発との関係&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現場の事象</th><th>この章の知識</th></tr></thead><tbody><tr><td>ECS/DOTSが「キャッシュフレンドリー」と言われる</td><td>SoA・連続配列</td></tr><tr><td><code>std::vector</code>推奨、<code>std::list</code>はほぼ禁止</td><td>ポインタ追跡の代償</td></tr><tr><td>パーティクルを構造体配列で持つ</td><td>AoS/SoAの選択</td></tr><tr><td>ジョブシステムでスレッド毎にバッファを分ける</td><td>false sharing回避</td></tr><tr><td>構造体のメンバ順を変えたらメモリが減った</td><td>パディング</td></tr><tr><td>「N体の敵AIが重い」→データ再設計で10倍</td><td>データ指向設計</td></tr></tbody></table><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><ol><li>同じ要素数の <code>std::vector&lt;int&gt;</code> と <code>std::list&lt;int&gt;</code> の全要素合計を計測し、 速度差(数倍〜数十倍)を確認せよ。理由をキャッシュラインで説明せよ。</li><li>2次元配列の走査を「行優先」「列優先」で計測し、差を確認せよ。</li><li>粒子10万個の更新を AoS版とSoA版で書き、位置更新のみ行う場合の 速度差を計測せよ。</li><li><code>struct A { char c; double d; int i; };</code> のサイズを予想→<code>sizeof</code>で確認 →メンバ並び替えで最小化せよ。<code>offsetof</code>で各メンバ位置も確認。</li><li>2スレッドが「隣接するint」をカウントアップするプログラムで false sharingを再現し、64Bラインの環境なら <code>alignas(64)</code> 等の分離を試して 計測せよ。CPU・データ配置・使用した整列値を記録する。</li></ol><h2 id="おすすめ書籍" tabindex="-1">おすすめ書籍 <a class="header-anchor" href="#おすすめ書籍" aria-label="Permalink to &quot;おすすめ書籍&quot;">​</a></h2><ul><li>『Game Engine Architecture(ゲームエンジン・アーキテクチャ)』 Jason Gregory ── メモリ章だけ先読み(全体は第15章で)</li><li>Ulrich Drepper &quot;What Every Programmer Should Know About Memory&quot; (無料PDF)── 決定版。難所は飛ばして良い</li><li>『Data-Oriented Design』Richard Fabian(無料Web版あり)── DODの原典</li><li>CS:APP 第6章(メモリ階層)</li></ul><h2 id="おすすめoss" tabindex="-1">おすすめOSS <a class="header-anchor" href="#おすすめoss" aria-label="Permalink to &quot;おすすめOSS&quot;">​</a></h2><ul><li><strong>EnTT</strong> (skypjack/entt) ── キャッシュ効率を極めたECS。今は README と 設計ドキュメントだけ読み、実装は第15章で</li><li>Google <strong>benchmark</strong> ライブラリ ── 計測演習の道具</li><li>mimalloc / tlsf ── アロケータのレイアウト工夫(第6章で再訪)</li></ul><h2 id="おすすめ動画" tabindex="-1">おすすめ動画 <a class="header-anchor" href="#おすすめ動画" aria-label="Permalink to &quot;おすすめ動画&quot;">​</a></h2><ul><li><strong>Mike Acton &quot;Data-Oriented Design and C++&quot; (CppCon 2014)</strong> ── ゲーム業界最重要講演のひとつ。Insomniac Games</li><li>Scott Meyers &quot;CPU Caches and Why You Care&quot;</li><li>CEDEC「データ指向設計」系講演(検索)</li></ul><h2 id="読むべきソースコード" tabindex="-1">読むべきソースコード <a class="header-anchor" href="#読むべきソースコード" aria-label="Permalink to &quot;読むべきソースコード&quot;">​</a></h2><ul><li>EnTTの <code>sparse_set.hpp</code>(密な配列に詰め直す工夫)※第15章で本格的に</li><li>UE5 <code>Engine/Source/Runtime/Core/Public/Containers/Array.h</code> (TArrayが連続メモリである事実だけ確認)</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>L1とDRAMのレイテンシはそれぞれ何サイクルの桁か?</li><li>キャッシュラインとは何バイトで、何を意味するか?</li><li>敵1000体の「座標だけ」を毎フレーム更新するとき、AoSとSoAの どちらが速いか。キャッシュラインの言葉で説明せよ。</li><li><code>std::list</code>がゲームのホットパスで嫌われる理由は?</li><li>false sharingとは何か。どう回避するか。</li><li>「このコードはメモリバウンドだ」とはどういう意味か。 どう確かめるか(第18章の予告)。</li></ol><hr><h2 id="この章がゲームのどこで使われているか" tabindex="-1">この章がゲームのどこで使われているか <a class="header-anchor" href="#この章がゲームのどこで使われているか" aria-label="Permalink to &quot;この章がゲームのどこで使われているか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1フレームの中身(CPU側)</span></span>
<span class="line"><span>┌───────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 物理更新     : 全剛体の座標配列を走査 → SoAが効く   │</span></span>
<span class="line"><span>│ アニメ更新   : ボーン行列の連続バッファ             │</span></span>
<span class="line"><span>│ カリング     : 全オブジェクトのAABB配列を走査        │</span></span>
<span class="line"><span>│ ECS更新      : コンポーネントを連続配置して一括処理  │</span></span>
<span class="line"><span>│ 描画コマンド : ソート済み配列を順に舐める            │</span></span>
<span class="line"><span>└───────────────────────────────────────────────┘</span></span>
<span class="line"><span>  ▲ 全部「配列をシーケンシャルに舐める」形に設計されている</span></span>
<span class="line"><span>    = この章のキャッシュ知識が全フレーム処理の設計原理</span></span>
<span class="line"><span>  ▲ GPUへ送る頂点/定数バッファのレイアウトにも同じ原理(第12章)</span></span></code></pre></div><h2 id="記述の確認資料" tabindex="-1">記述の確認資料 <a class="header-anchor" href="#記述の確認資料" aria-label="Permalink to &quot;記述の確認資料&quot;">​</a></h2><ul><li><a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel-sdm.html" target="_blank" rel="noreferrer">Intel 64 and IA-32 Architecture / Optimization manuals</a></li><li><a href="https://eel.is/c++draft/hardware.interference" target="_blank" rel="noreferrer">C++ working draft: Hardware interference size</a></li><li><a href="https://www.open-std.org/jtc1/sc22/wg14/www/docs/n1570.pdf" target="_blank" rel="noreferrer">WG14 N1570: C11 committee draft (5.1.2.3, 6.2.4, 6.5, 6.7.2.1)</a></li></ul>`,30)])])}const g=l(n,[["render",s]]);export{u as __pageData,g as default};
